'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const A = data[0];
const B = data[1];

let j = 0;
for (let i = 0; i < A && j < B; i++) {
  if (data[2 + i] === data[2 + A + j]) j++;
}

console.log(j === B ? 'S' : 'N');
